import { describe, expect, it } from 'vitest';

import { DM, ELOWEN, PLAYER } from '../authoring/testing/world.ts';
import { codeOf } from './testing/world.ts';
import { visualWorld } from '../visual/testing/world.ts';
import { assetLineage } from './views.ts';

/**
 * A player's wish for their own character's portrait (docs/adr/0056-characters-from-the-srd.md
 * §5): kept as a world fact for the DM; the DM's request for the character's picture answers it,
 * and undoing that request brings it back. Nothing is generated by the wish.
 */
const ask = (look: string, characterId = ELOWEN, actor = PLAYER) => ({
  actor,
  command: { type: 'AskPortrait', characterId, look },
});

describe('a wish for a portrait', () => {
  it('is the player’s for their own character, kept for the DM', async () => {
    const world = await visualWorld();
    const wish = ask('Silver hair, a grey cloak, a yew longbow');
    expect(codeOf(await world.as(wish.actor, wish.command))).toBe('accepted');
    expect(codeOf(await world.as(wish.actor, wish.command))).toBe('NO_EFFECT');
    const other = ask('Someone else', 'mira-vale');
    expect(codeOf(await world.as(other.actor, other.command))).toBe('FORBIDDEN');
    const state = await world.state();
    expect(assetLineage(state).wishes).toEqual([
      { characterId: ELOWEN, look: 'Silver hair, a grey cloak, a yew longbow' },
    ]);
    // No request is made by the wish: the image model is asked only by the DM.
    expect(state.assets.requests.size).toBe(0);
    await world.verified();
  });

  it('is answered by the DM’s request, and back when the request is undone', async () => {
    const world = await visualWorld();
    await world.as(PLAYER, ask('Silver hair').command);
    const request = await world.as(DM, {
      type: 'RequestAsset',
      entityId: ELOWEN,
      variant: 'reference',
      note: 'Silver hair',
    });
    expect(codeOf(request)).toBe('accepted');
    expect((await world.state()).portraitWishes.size).toBe(0);
    expect(codeOf(await world.undo(request.commandId ?? ''))).toBe('accepted');
    expect((await world.state()).portraitWishes.get(ELOWEN)).toBe('Silver hair');
    await world.verified();
  });
});
